<!-- ============ 3. OPT-OUT ============ -->
<section id="optout" aria-labelledby="h-optout">
  <div class="sec-head">
    <span class="eyebrow">Схема 3 · Цена давления</span>
    <h2 id="h-optout">0,25% на отправку выглядит мелочью, но отписки копятся</h2>
    <p>Каждый пуш отнимает небольшую долю подписчиков. При трёх пушах в день за месяц уходит примерно каждый пятый.</p>
  </div>
  <figure class="fig">
    <div class="fig-panel narrow">
      <svg class="dg" viewBox="0 0 660 300" role="img" aria-label="График: доля отписавшихся от пушей растёт с числом отправок. После 30 пушей около 7 процентов, после 90 пушей около 20 процентов.">
        <g class="grid">
          <path d="M60,250 H600"/><path d="M60,206 H600"/><path d="M60,162 H600"/><path d="M60,118 H600"/><path d="M60,74 H600"/><path d="M60,30 H600"/>
        </g>
        <g>
          <text class="tm" x="52" y="254" text-anchor="end">0%</text>
          <text class="tm" x="52" y="210" text-anchor="end">5%</text>
          <text class="tm" x="52" y="166" text-anchor="end">10%</text>
          <text class="tm" x="52" y="122" text-anchor="end">15%</text>
          <text class="tm" x="52" y="78" text-anchor="end">20%</text>
          <text class="tm" x="52" y="34" text-anchor="end">25%</text>
          <text class="tm" x="60" y="268" text-anchor="middle">0</text>
          <text class="tm" x="240" y="268" text-anchor="middle">30</text>
          <text class="tm" x="420" y="268" text-anchor="middle">60</text>
          <text class="tm" x="600" y="268" text-anchor="middle">90</text>
          <text class="tm" x="330" y="290" text-anchor="middle">пушей одному человеку за месяц</text>
        </g>
        <path class="ln ln-h" style="stroke-width:2.5" d="M60,250 L120,228.3 L180,207.1 L240,186.4 L300,166.1 L360,146.5 L420,127.3 L480,108.6 L540,90.3 L600,72.5"/>
        <circle class="dot" cx="240" cy="186.4" r="5"/>
        <text x="252" y="212">1 пуш в день: отписались ≈7%</text>
        <circle class="dot" cx="600" cy="72.5" r="5"/>
