  --font-mono:"JetBrains Mono",ui-monospace,Menlo,Consolas,monospace;
  --text-sm:.875rem; --text-xs:.75rem;
  --space-section:clamp(3rem,2rem + 4vw,5rem);
}
@media (prefers-color-scheme: dark){
  :root:not([data-theme="light"]){
    --bg:#0F131C; --surface:#171D2A; --box:#202838; --ink:#E8ECF4; --muted:#9AA4B8; --line:#36425A;
    --accent:#82A8FF; --accent-soft:#1A2848; --on-accent:#0F131C;
    --hot:#FF8F6B; --hot-soft:#3D2018; color-scheme:dark;
  }
}
:root[data-theme="dark"]{
  --bg:#0F131C; --surface:#171D2A; --box:#202838; --ink:#E8ECF4; --muted:#9AA4B8; --line:#36425A;
  --accent:#82A8FF; --accent-soft:#1A2848; --on-accent:#0F131C;
  --hot:#FF8F6B; --hot-soft:#3D2018; color-scheme:dark;
}
*{box-sizing:border-box}
body{background:var(--bg);color:var(--ink);font-family:var(--font-body);font-size:1rem;line-height:1.55;margin:0;padding-inline:clamp(16px,4vw,40px);padding-block:clamp(28px,5vw,64px)}
.page{max-width:1040px;margin-inline:auto;display:flex;flex-direction:column;gap:var(--space-section)}
h1,h2,h3{margin:0;text-wrap:balance;line-height:1.15}
h1{font-size:clamp(1.9rem,1.2rem + 2.6vw,3rem);font-weight:700;letter-spacing:-.02em}
h2{font-size:clamp(1.3rem,1.1rem + .8vw,1.7rem);font-weight:700;letter-spacing:-.01em}
h3{font-size:1rem;font-weight:600}
p{margin:0;max-width:65ch}
a{color:var(--accent)}
a:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:2px}
.eyebrow{font-family:var(--font-mono);font-size:var(--text-xs);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.muted{color:var(--muted)}

.top{display:flex;flex-direction:column;gap:1rem}
.top .lede{font-size:1.125rem}
.legend{display:flex;flex-wrap:wrap;gap:.5rem 1.5rem;font-size:var(--text-sm);color:var(--muted)}
.legend span{display:inline-flex;align-items:center;gap:.5rem}
.legend i{width:.875rem;height:.875rem;border-radius:3px;border:1.5px solid var(--accent);background:var(--accent-soft)}
.legend i.h{border-color:var(--hot);background:var(--hot-soft)}
.toc{display:flex;flex-wrap:wrap;gap:.375rem 1.25rem;margin:0;padding:0;list-style:none;font-size:var(--text-sm)}
.toc a{text-decoration:none;border-bottom:1px solid var(--line)}
.toc a:hover{border-bottom-color:var(--accent)}

section{display:flex;flex-direction:column;gap:1.25rem;scroll-margin-top:1rem}
.sec-head{display:flex;flex-direction:column;gap:.5rem}
.fig{margin:0;display:flex;flex-direction:column;gap:.75rem}
.fig-panel{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:clamp(12px,2vw,24px);overflow-x:auto}
.fig-panel svg{display:block;width:100%;min-width:780px;height:auto}
.fig-panel.narrow svg{min-width:520px;max-width:720px}
figcaption{font-size:var(--text-sm);color:var(--muted);max-width:75ch}

/* diagram marks */
.dg text{font-family:var(--font-body);font-size:12.5px;fill:var(--ink)}
.dg .tb{font-weight:600;font-size:13px}
.dg .tm{fill:var(--muted);font-size:11.5px}
.dg .tn{font-family:var(--font-mono);font-size:11px;font-weight:500;fill:var(--accent)}
.dg .th{fill:var(--hot)}
.dg .to{fill:var(--on-accent)}
.dg .cap{font-size:10.5px;font-weight:600;letter-spacing:.08em;fill:var(--muted)}
.dg .bx{fill:var(--box);stroke:var(--line)}
.dg .bx-p{fill:var(--surface);stroke:var(--line)}
.dg .bx-a{fill:var(--accent-soft);stroke:var(--accent)}
.dg .bx-h{fill:var(--hot-soft);stroke:var(--hot)}
.dg .bx-s{fill:var(--accent);stroke:var(--accent)}
.dg .strong{stroke-width:2}
.dg .dash{stroke-dasharray:5 4}
.dg .ln{fill:none;stroke:var(--muted);stroke-width:1.2}
.dg .ln-a{stroke:var(--accent)}
.dg .ln-h{stroke:var(--hot)}
.dg .thin{stroke-width:.9;opacity:.8}
.dg .grid{stroke:var(--line);stroke-width:1;fill:none}
.dg .ah{fill:var(--muted)}
.dg .ah-a{fill:var(--accent)}
.dg .ah-h{fill:var(--hot)}
.dg .dot{fill:var(--hot);stroke:var(--surface);stroke-width:2}

/* consequences under figure 1 */
.trio{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem 2rem;margin:0;padding:0;list-style:none}
.trio li{border-top:2px solid var(--hot);padding-top:.625rem;min-width:0}
.trio b{display:block;font-weight:600}
.trio span{font-size:var(--text-sm);color:var(--muted)}

/* numbers */
.nums{display:flex;flex-direction:column;gap:2rem}
.num-group{display:flex;flex-direction:column;gap:.25rem}
.num-group h3{font-family:var(--font-mono);font-size:var(--text-xs);letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:500;padding-bottom:.5rem}
.num-row{display:grid;grid-template-columns:8.5rem minmax(0,1fr);gap:.25rem 1.5rem;padding-block:.875rem;border-top:1px solid var(--line);align-items:start}
.num-val{font-family:var(--font-mono);font-size:1.5rem;font-weight:600;font-variant-numeric:tabular-nums;line-height:1.1;white-space:nowrap}
.num-val small{display:block;font-size:var(--text-xs);font-weight:400;color:var(--muted);white-space:normal;padding-top:.25rem}
.num-body{display:flex;flex-direction:column;gap:.375rem;min-width:0}
.num-body b{font-weight:600}
.num-body span{font-size:var(--text-sm);color:var(--muted);max-width:65ch}
.bar{height:6px;border-radius:3px;background:var(--line);max-width:28rem;overflow:hidden}
.bar i{display:block;height:100%;min-width:3px;background:var(--accent);border-radius:3px}
.bar.h i{background:var(--hot)}
@media (max-width:520px){.num-row{grid-template-columns:1fr}}

/* open questions */
.checks{display:flex;flex-direction:column;gap:0;margin:0;padding:0;list-style:none;counter-reset:q}
.checks li{display:grid;grid-template-columns:2rem minmax(0,1fr);gap:.25rem .5rem;padding-block:.875rem;border-top:1px solid var(--line);counter-increment:q}
.checks li::before{content:counter(q);font-family:var(--font-mono);font-size:var(--text-sm);color:var(--muted)}
.checks b{display:block;font-weight:600}
.checks span{font-size:var(--text-sm);color:var(--muted);max-width:70ch;display:block}
.foot{font-size:var(--text-sm);color:var(--muted);border-top:1px solid var(--line);padding-top:1rem}
</style>

