        <!-- row 2 -->
        <rect class="bx" x="20" y="120" width="310" height="60" rx="4"/>
        <text class="tb" x="36" y="145">Ипотека · пуш</text>
        <text class="tm" x="36" y="164">«Рассчитайте платёж по этой квартире»</text>
        <path class="ln" d="M330,150 H378" marker-end="url(#m7m)"/>
