/* numbers */
.nums{display:flex;flex-direction:column;gap:2rem}
.num-group{display:flex;flex-direction:column;gap:.25rem}
.num-group h3{font-family:var(--font-mono);font-size:var(--text-xs);letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:500;padding-bottom:.5rem}
.num-row{display:grid;grid-template-columns:8.5rem minmax(0,1fr);gap:.25rem 1.5rem;padding-block:.875rem;border-top:1px solid var(--line);align-items:start}
.num-val{font-family:var(--font-mono);font-size:1.5rem;font-weight:600;font-variant-numeric:tabular-nums;line-height:1.1;white-space:nowrap}
.num-val small{display:block;font-size:var(--text-xs);font-weight:400;color:var(--muted);white-space:normal;padding-top:.25rem}
.num-body{display:flex;flex-direction:column;gap:.375rem;min-width:0}
.num-body b{font-weight:600}
.num-body span{font-size:var(--text-sm);color:var(--muted);max-width:65ch}
.bar{height:6px;border-radius:3px;background:var(--line);max-width:28rem;overflow:hidden}
.bar i{display:block;height:100%;min-width:3px;background:var(--accent);border-radius:3px}
.bar.h i{background:var(--hot)}
@media (max-width:520px){.num-row{grid-template-columns:1fr}}

/* open questions */
.checks{display:flex;flex-direction:column;gap:0;margin:0;padding:0;list-style:none;counter-reset:q}
.checks li{display:grid;grid-template-columns:2rem minmax(0,1fr);gap:.25rem .5rem;padding-block:.875rem;border-top:1px solid var(--line);counter-increment:q}
.checks li::before{content:counter(q);font-family:var(--font-mono);font-size:var(--text-sm);color:var(--muted)}
.checks b{display:block;font-weight:600}
.checks span{font-size:var(--text-sm);color:var(--muted);max-width:70ch;display:block}
.foot{font-size:var(--text-sm);color:var(--muted);border-top:1px solid var(--line);padding-top:1rem}
</style>

